const D = { energy:.6, density:.5, scale:1, hue:210, speed:1, x:.5, y:.5, alpha:.95, depth:.6, style:'matisse', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const t = K.t;
const drift = 0.9*Math.sin(t*0.61) + 0.5*Math.sin(t*1.43+1.7) + 0.32*Math.sin(t*2.29);
const swell = (K.swell!=null ? K.swell : 0.5+0.5*Math.sin(t*0.4));
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return s - Math.floor(s); };

const st = P.style;
// paper palettes (HSB): return [h,s,b] for shape index
function paper(i){
  const r = fr(i*9+5), r2 = fr(i*9+6);
  if (st==='kraft'){ const set=[[34,42,70],[28,55,58],[70,32,52],[14,58,60],[40,18,86],[30,12,26]]; return set[(r*set.length)|0]; }
  if (st==='kirigami'){ return [ (P.hue+ (r-0.5)*20+360)%360, 6+8*r2, 90-14*r ]; }
  if (st==='collage'){ return [ (r*360)|0, 22+30*r2, 55+30*r2 ]; }
  if (st==='botanical'){ const g=[[120,55,48],[95,60,42],[142,48,58],[70,50,55],[40,60,72],[330,52,72]]; return g[(r*g.length)|0]; }
  const set=[[P.hue,80,80],[(P.hue+150)%360,78,72],[(P.hue+40)%360,85,88],[(P.hue+300)%360,70,74],[20,80,78],[0,0,12]]; // matisse
  return set[(r*set.length)|0];
}
const ground = st==='kraft'?[36,26,80]: st==='kirigami'?[210,8,90]: st==='botanical'?[42,20,88]: st==='collage'?[40,10,82] : [P.hue,24,86];

// build shapes cache
const bkey = P.seed+'|'+st+'|'+Math.round(P.density*20)+'|'+Math.round(P.hue)+'|'+Math.round(P.scale*10);
if (!S.shapes || S.skey !== bkey){
  S.skey = bkey;
  const M = Math.round(7 + 30*P.density);
  const arr = [];
  for (let i=0;i<M;i++){
    const np = 7 + (fr(i*4+1)*7|0);
    const wob = [];
    for (let a=0;a<np;a++) wob.push(0.62 + 0.5*fr(i*40+a));
    arr.push({
      bx: fr(i*4+2), by: fr(i*4+3),
      r: (0.09 + 0.2*fr(i*4+4)) * P.scale,
      col: paper(i),
      leaf: fr(i*4+7) > 0.62,
      rot0: fr(i*4+5)*Math.PI*2,
      orb: 0.02+0.05*fr(i*4+6),
      oph: fr(i*4+8)*6.283,
      z: i/M, np, wob
    });
  }
  arr.sort((a,b)=>a.r-b.r);   // big first (back), small last (front)
  S.shapes = arr.reverse();
}

function blob(cx, cy, r, rot, np, wob){
  beginShape();
  const aa0 = rot + (np-1)/np*Math.PI*2, rr0=r*wob[np-1];
  curveVertex(cx+Math.cos(aa0)*rr0, cy+Math.sin(aa0)*rr0);
  for (let a=0;a<np;a++){
    const aa = rot + a/np*Math.PI*2;
    const rr = r*wob[a];
    curveVertex(cx+Math.cos(aa)*rr, cy+Math.sin(aa)*rr);
  }
  for (let a=0;a<2;a++){ const aa=rot+a/np*Math.PI*2, rr=r*wob[a]; curveVertex(cx+Math.cos(aa)*rr, cy+Math.sin(aa)*rr); }
  endShape(CLOSE);
}

const lightAng = 0.9 + t*0.02*P.speed + 0.25*drift;   // slow light-direction rotation
const ldx = Math.cos(lightAng), ldy = Math.sin(lightAng);
const off = u*(0.012 + 0.05*P.depth);

push();
// paper ground
blendMode(BLEND); noStroke();
fill(ground[0], ground[1], ground[2], 100*P.alpha);
rect(0,0,width,height);

for (const s of S.shapes){
  const ph = t*s.orb*P.speed + s.oph;
  const cx = width*(0.08 + 0.84*s.bx) + Math.cos(ph)*width*0.03*(0.4+s.z) + 0.01*drift*width;
  const cy = height*(0.1 + 0.8*s.by) + Math.sin(ph*1.3)*height*0.03*(0.4+s.z);
  const rot = s.rot0 + t*0.01*(s.leaf?1:0.4)*P.speed;
  const r = u*s.r*(1 + 0.03*Math.sin(t*0.3+s.oph));
  const zoff = off*(0.5 + s.z);   // nearer shapes cast longer shadows
  // fake-blurred drop shadow: 3 offset dark copies
  for (let k=3;k>=1;k--){
    const o = zoff*k*0.9;
    fill(ground[0], Math.min(60,ground[1]+20), ground[2]*(0.28), (10+22*P.energy)*P.alpha*(1.1-k*0.22));
    blob(cx+ldx*o, cy+ldy*o, r, rot, s.np, s.wob);
  }
  // paper body (opaque)
  fill(s.col[0], s.col[1], s.col[2], 100*P.alpha);
  blob(cx, cy, r, rot, s.np, s.wob);
  // subtle raking sheen on the lit edge (ADD, thin)
  blendMode(ADD);
  noFill(); stroke(s.col[0], s.col[1]*0.5, 100, (18+26*P.energy)*P.alpha*(0.6+0.4*swell)); strokeWeight(Math.max(1, r*0.04));
  push(); translate(-ldx*r*0.04,-ldy*r*0.04); blob(cx, cy, r*0.97, rot, s.np, s.wob); pop();
  noStroke(); blendMode(BLEND);
}

pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
